// Generates .github/instructions/bi-<rule>.instructions.md from .claude/rules/bi/*.md: GitHub Copilot in VS Code
// does not load Claude's path-scoped rules, but it applies an instructions file whose `applyTo` globs match the file
// being edited (VS Code docs, custom instructions). Each generated file is a pointer ("read and follow this rule"),
// never a copy, so the rule text lives in one place. Usage: node hardening/scripts/sync-copilot-instructions.mjs
// [--check]  (--check exits 1 when a generated file is missing or stale; tests/copilot-instructions.test.mjs runs it).
// Both exit 1 when a rule has a `paths:` key the generator cannot read (it reads block lists of quoted or bare items,
// flow lists and a single value).
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');
const RULES = path.join(ROOT, '.claude', 'rules', 'bi');
const OUT = path.join(ROOT, '.github', 'instructions');
const check = process.argv.includes('--check');

/** One YAML scalar: "double" (\" and \\ escapes), 'single' ('' is a quote) or bare (a ` #` comment ends it). */
function scalar(raw) {
  const v = raw.trim();
  const dq = /^"((?:[^"\\]|\\.)*)"\s*(?:#.*)?$/.exec(v);
  if (dq) return dq[1].replace(/\\(.)/g, '$1');
  const sq = /^'((?:[^']|'')*)'\s*(?:#.*)?$/.exec(v);
  if (sq) return sq[1].replace(/''/g, "'");
  return v.replace(/(?:^|\s+)#.*$/, '').trim();
}

/**
 * The globs of a rule's frontmatter `paths:` key (F1-137): a block list whose items are double-quoted, single-quoted or
 * bare, a flow list ([a, "b"]) or a single value. null when the frontmatter has no `paths:` key (the rule applies
 * everywhere: no pointer); [] when it has one that reads as no glob, which the caller reports instead of skipping.
 */
function pathsOf(text) {
  const fm = /^---\r?\n([\s\S]*?)\r?\n---/.exec(text);
  if (!fm) return null;
  const lines = fm[1].split(/\r?\n/);
  const at = lines.findIndex((l) => /^paths\s*:/.test(l));
  if (at === -1) return null;
  const inline = lines[at].replace(/^paths\s*:/, '').trim();
  if (inline && !inline.startsWith('#')) {
    const flow = /^\[(.*)\]\s*(?:#.*)?$/.exec(inline);
    if (!flow) return [scalar(inline)].filter(Boolean);
    const items = flow[1].match(/"(?:[^"\\]|\\.)*"|'(?:[^']|'')*'|[^,]+/g) ?? [];
    return items.map(scalar).filter(Boolean);
  }
  // A block list: the `- item` lines right below the key (indented or not), up to the next key.
  const out = [];
  for (const line of lines.slice(at + 1)) {
    if (!line.trim() || /^\s*#/.test(line)) continue;
    const item = /^\s*-(?:\s+(.*))?$/.exec(line);
    if (!item) break;
    out.push(scalar(item[1] ?? ''));
  }
  return out.filter(Boolean);
}

/** Rules whose `paths:` key reads as no glob: --check and the sync fail on them rather than skip them silently. */
const unreadable = [];

export function expectedFiles() {
  const out = new Map();
  unreadable.length = 0;
  for (const name of fs.readdirSync(RULES).filter((f) => f.endsWith('.md')).sort()) {
    const rule = name.replace(/\.md$/, '');
    const paths = pathsOf(fs.readFileSync(path.join(RULES, name), 'utf8'));
    if (paths === null) continue;
    if (!paths.length) {
      unreadable.push(name);
      continue;
    }
    const text = [
      '---',
      `applyTo: "${paths.join(',')}"`,
      `description: "BI Agent Harness: the ${rule} rules of .claude/rules/bi/${rule}.md apply to these files"`,
      '---',
      '',
      `Generated by \`hardening/scripts/sync-copilot-instructions.mjs\` from \`.claude/rules/bi/${rule}.md\`; do not edit here.`,
      '',
      `Before you read or change a file this applies to, read \`.claude/rules/bi/${rule}.md\` and follow it. \`AGENTS.md\` is the`,
      'working agreement; the skills under `.claude/skills/` hold the procedures (start with `.claude/skills/bi-map/SKILL.md`).',
      '',
    ].join('\n');
    out.set(`bi-${rule}.instructions.md`, text);
  }
  return out;
}

const expected = expectedFiles();
let stale = 0;
for (const [file, text] of expected) {
  const dest = path.join(OUT, file);
  const current = fs.existsSync(dest) ? fs.readFileSync(dest, 'utf8').replace(/\r\n/g, '\n') : null;
  if (current === text) continue;
  stale++;
  if (check) console.log(`${current === null ? 'missing' : 'stale'}: .github/instructions/${file}`);
  else {
    fs.mkdirSync(OUT, { recursive: true });
    fs.writeFileSync(dest, text);
    console.log(`${current === null ? 'written' : 'updated'}: .github/instructions/${file}`);
  }
}
if (fs.existsSync(OUT)) {
  // The pointer of a rule whose paths cannot be read stays: that rule is reported below, not treated as gone.
  const kept = new Set(unreadable.map((name) => `bi-${name.replace(/\.md$/, '')}.instructions.md`));
  for (const file of fs.readdirSync(OUT).filter((f) => /^bi-.*\.instructions\.md$/.test(f) && !expected.has(f) && !kept.has(f))) {
    stale++;
    if (check) console.log(`orphan: .github/instructions/${file} (no rule .claude/rules/bi/${file.replace(/^bi-|\.instructions\.md$/g, '')}.md)`);
    else {
      fs.unlinkSync(path.join(OUT, file));
      console.log(`removed: .github/instructions/${file}`);
    }
  }
}
for (const name of unreadable) console.log(`unreadable: .claude/rules/bi/${name} has a paths: key but no glob the generator can read`);
console.log(`${expected.size} instruction file(s) ${check ? 'checked' : 'in sync'}; ${stale} ${check ? 'out of date' : 'changed'}`);
if ((check && stale) || unreadable.length) process.exit(1);
